mapper.select:
SELECT * FROM rec_onboarding

    deleted = 0

        AND candidate_id = #{params.candidateId}


        AND status = #{params.status}


        AND expected_onboard_date >= #{params.startDate}


        AND expected_onboard_date <= #{params.endDate}


        AND employee_no LIKE CONCAT('%', #{params.employeeNo}, '%')


        AND employee_name LIKE CONCAT('%', #{params.employeeName}, '%')


        AND department_name LIKE CONCAT('%', #{params.departmentName}, '%')


        AND position_title LIKE CONCAT('%', #{params.positionTitle}, '%')


        AND employee_status = #{params.employeeStatus}


        AND current_step = #{params.currentStep}


ORDER BY create_time DESC
